def priority(processing_time, remaining_work, remaining_operations, job_ready_time, machine_ready_time, earliest_start, earliest_finish):
    p = processing_time
    if p != p:
        p = 1000000000.0
    if p < 0.0:
        p = 0.0
    if p > 1000000000.0:
        p = 1000000000.0
    work = remaining_work
    if work != work:
        work = 0.0
    if work < 0.0:
        work = 0.0
    if work > 1000000000.0:
        work = 1000000000.0
    operations = remaining_operations
    if operations != operations:
        operations = 1.0
    if operations < 1.0:
        operations = 1.0
    if operations > 1000000000.0:
        operations = 1000000000.0
    ready = job_ready_time
    if ready != ready:
        ready = 0.0
    if ready < 0.0:
        ready = 0.0
    if ready > 1000000000.0:
        ready = 1000000000.0
    finish = earliest_finish
    if finish != finish:
        finish = 1000000000.0
    if finish < 0.0:
        finish = 0.0
    if finish > 1000000000.0:
        finish = 1000000000.0
    average = work / operations
    delay = finish - ready
    if delay < p:
        delay = p
    criticality = ready + work
    machine_factor = (1.0 + average) / (1.0 + average + delay)
    score = criticality * machine_factor
    return score
